use crate::effects::{Frame,Params};use crate::keyframe::Prop;
#[test]fn exact_grid(){for(w,h)in[(1,1),(7,13),(128,65)]{for size in [1.,1.5,2.3,8.]{for seed in [0,42,u64::MAX]{let mut p=Params::new();p.insert("grain_size".into(),Prop::new(size));let mut a=Frame::new(w,h);for(i,v)in a.d.iter_mut().enumerate(){*v=if i%4==3{if i%3==0{0.}else{0.4}}else{-2.+4.*i as f32/(w*h*4) as f32};}let mut b=Frame{w,h,d:a.d.clone()};super::finish_v2_reference::apply(&p,&mut a,0.,seed).unwrap();super::finish::apply(&p,&mut b,0.,seed).unwrap();assert_eq!(a.d,b.d,"{w} {h} {size} {seed}");}}}}
#[test]#[ignore]fn real_benchmark(){let bytes=std::fs::read("/tmp/perf1080.rgba").unwrap();let input:Vec<_>=bytes.iter().map(|v|*v as f32/255.).collect();let mut times=[Vec::new(),Vec::new()];for _ in 0..5{let mut a=Frame{w:1920,h:1080,d:input.clone()};let mut b=Frame{w:1920,h:1080,d:input.clone()};let p=Params::new();let now=std::time::Instant::now();super::finish_v2_reference::apply(&p,&mut a,0.,42).unwrap();times[0].push(now.elapsed().as_secs_f64());let now=std::time::Instant::now();super::finish::apply(&p,&mut b,0.,42).unwrap();times[1].push(now.elapsed().as_secs_f64());assert_eq!(a.d,b.d);std::fs::write("/tmp/adjust-v2.f32",b.d.iter().flat_map(|v|v.to_le_bytes()).collect::<Vec<_>>()).unwrap();}for v in &mut times{v.sort_by(f64::total_cmp)}println!("FINISHV2 old{} new{} speed{} exact=true",times[0][2],times[1][2],times[0][2]/times[1][2]);}
#[test]#[ignore]fn stage_profile(){let bytes=std::fs::read("/tmp/perf1080.rgba").unwrap();let f=Frame{w:1920,h:1080,d:bytes.iter().map(|v|*v as f32/255.).collect()};for(stage,fx)in[("full",0),("grain_vignette",1),("bloom_only",2),("print_stock",3),("blur",4)]{let mut p=Params::new();if fx==1{for k in ["bloom","halation"]{p.insert(k.into(),Prop::new(0.));}}if fx==2{for k in ["grain","vignette"]{p.insert(k.into(),Prop::new(0.));}}let mut times=Vec::new();for _ in 0..3{let mut a=Frame{w:f.w,h:f.h,d:f.d.clone()};let now=std::time::Instant::now();match fx{3=>super::printstock::apply(&p,&mut a,0.).unwrap(),4=>super::blur_v2_reference::blur(&mut a,19),_=>super::finish_v2_reference::apply(&p,&mut a,0.,42).unwrap()}times.push(now.elapsed().as_secs_f64());}times.sort_by(f64::total_cmp);println!("STAGE {stage} {}",times[1]);}}
#[test]fn blocked_blur_exact(){for(w,h)in[(1,1),(3,17),(65,33),(127,100)]{for r in [1,2,9,64,512]{let mut a=Frame::new(w,h);for(i,v)in a.d.iter_mut().enumerate(){*v=if i%4==3{0.4}else{((i*37)%997) as f32/997.-0.3};}let mut b=Frame{w,h,d:a.d.clone()};super::blur_v2_reference::blur(&mut a,r);super::blur::blur(&mut b,r);assert_eq!(a.d,b.d,"{w}x{h} radius{r}");}}}
